  var angOf = function (p, q) { return deg(Math.atan2(q[1] - p[1], q[0] - p[0])); };
  // Per-mirror IN-PLANE tilt from the in/out chords (identical to the 2D loop —
  // orientation is z-axis rotation; the slab depth adds NO new angle).
